    <a class="skip-link" href="#main">Skip to main content</a>
    <div id="app"></div>

    <script>
      const faqs = [
        {
          question: "Why do cats purr?",
          answer:
            "Cats often purr when they feel relaxed, but purring can also be a self-soothing behavior when they are stressed, recovering, or asking for comfort."
        },
        {
          question: "How much sleep do cats need?",
          answer:
            "Most adult cats sleep 12 to 16 hours a day. Kittens and senior cats may sleep even more because growth, play, and recovery all take energy."
        },
        {
          question: "Why do cats knead blankets or people?",
          answer:
            "Kneading is a leftover kitten behavior associated with nursing. Adult cats often knead when they are content, marking a cozy place, or settling in for rest."
        },
        {
          question: "Should cats drink milk?",
          answer:
            "Many cats are lactose intolerant, so cow's milk can upset their stomachs. Fresh water is the safest everyday drink for cats."
        },
        {
          question: "How can I tell if a cat is happy?",
          answer:
            "A happy cat may show relaxed ears, slow blinking, a softly raised tail, gentle purring, playful curiosity, and a willingness to nap near trusted people."
        }
      ];

      function Header() {
        return `
          <header>
            <p class="eyebrow">Feline field notes</p>
            <h1>Cat FAQ</h1>
            <p class="intro">
              Quick answers to common questions about cat behavior, care, and communication.
              Each question starts collapsed and can be expanded independently.
            </p>
          </header>
        `;
      }

      function FAQItem({ question, answer }, index) {
        const buttonId = `faq-button-${index + 1}`;
        const panelId = `faq-panel-${index + 1}`;

        return `
          <div class="example">
            <h2>
              <button
                class="question-button"
                id="${buttonId}"
                type="button"
                aria-expanded="true"
                aria-controls="${panelId}"
              >
                ${question}
              </button>
            </h2>
            <div class="details" id="${panelId}" aria-labelledby="${buttonId}">
              <p>${answer}</p>
            </div>
          </div>
        `;
      }

      function FAQList(items) {
        return `<section class="faq-list" aria-label="Cat questions">${items.map(FAQItem).join("")}</section>`;
      }

      function App() {
        return `
          <div class="page-shell">
            ${Header()}
            <main id="main">
              ${FAQList(faqs)}
            </main>
            <footer>
              <p>Tip: slow blinks are often a friendly cat greeting.</p>
            </footer>
          </div>
        `;
      }

      document.querySelector("#app").innerHTML = App();

      document.querySelectorAll(".question-button").forEach((button) => {
        const panel = document.getElementById(button.getAttribute("aria-controls"));
        button.setAttribute("aria-expanded", "false");
        panel.hidden = true;

        button.addEventListener("click", () => {
          const isOpen = button.getAttribute("aria-expanded") === "true";
          button.setAttribute("aria-expanded", String(!isOpen));
          panel.hidden = isOpen;
